type PageViewEvent = {
  path: string
  timestamp: string
  userAgent: string | null
}

export async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    console.log('[analytics] page view', event)
    return
  }

  try {
    await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'page_view', ...event }),
    })
  } catch (error) {
    console.error('[analytics] failed to log page view', error)
  }
}

